<?php

namespace IAWP\Geo;

use IAWP\Utils\Security;
/** @internal */
class CloudflareGeo
{
    public static function is_available() : bool
    {
        return !\is_null(self::get());
    }
    public static function get() : ?\IAWP\Geo\Geo
    {
        $city = self::header('HTTP_CF_IPCITY');
        $country_code = self::header('HTTP_CF_IPCOUNTRY') ?? '';
        $continent_code = self::header('HTTP_CF_IPCONTINENT') ?? '';
        $region = self::header('HTTP_CF_REGION');
        $country = self::country_name($country_code);
        $continent = self::continent_name($continent_code);
        return \IAWP\Geo\Geo::from_values($continent, $country_code, $country, $city, $region);
    }
    private static function header(string $header) : ?string
    {
        if (!isset($_SERVER[$header]) || !\is_string($_SERVER[$header])) {
            return null;
        }
        $value = Security::string($_SERVER[$header]);
        return $value === '' ? null : $value;
    }
    private static function continent_name(string $continent_code) : ?string
    {
        $continents = ['AF' => 'Africa', 'AN' => 'Antarctica', 'AS' => 'Asia', 'EU' => 'Europe', 'NA' => 'North America', 'OC' => 'Oceania', 'SA' => 'South America'];
        return $continents[\strtoupper($continent_code)] ?? null;
    }
